package org.sleepwell.app;
import org.json.*;import java.util.*;
final class PictureReferenceJson {
    static JSONObject encode(PictureReference reference){try{return new JSONObject().put("version",1).put("label",reference.label).put("hash",String.format(Locale.ROOT,"%016x",reference.signature.hash)).put("mean",reference.signature.mean).put("contrast",reference.signature.contrast).put("gradient",reference.signature.gradient).put("histogram",new JSONArray(reference.signature.histogram)).put("edges",new JSONArray(reference.signature.edges));}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
    static PictureReference decode(Object raw)throws JSONException{if(!(raw instanceof JSONObject row)||row.length()!=8)throw new JSONException("Invalid picture reference");Set<String> keys=Set.of("version","label","hash","mean","contrast","gradient","histogram","edges");for(Iterator<String> it=row.keys();it.hasNext();)if(!keys.contains(it.next()))throw new JSONException("Unknown picture reference field");try{if(integer(row.get("version"))!=1||!(row.get("label") instanceof String)||!(row.get("hash") instanceof String hash)||!hash.matches("[0-9a-f]{16}"))throw new IllegalArgumentException();return new PictureReference(row.getString("label"),new PictureSignature(Long.parseUnsignedLong(hash,16),integer(row.get("mean")),integer(row.get("contrast")),integer(row.get("gradient")),array(row.get("histogram"),16),array(row.get("edges"),64)));}catch(RuntimeException invalid){throw new JSONException("Invalid picture signature or label");}}
    private static int integer(Object raw)throws JSONException{if(!(raw instanceof Integer))throw new JSONException("Picture values must be integers");return (Integer)raw;}private static int[] array(Object raw,int count)throws JSONException{if(!(raw instanceof JSONArray array)||array.length()!=count)throw new JSONException("Invalid picture descriptor length");int[] values=new int[count];for(int n=0;n<count;n++)values[n]=integer(array.get(n));return values;}
}
